use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut comp: Vec<bool> = []
    let mut count: Vec<int> = []
    let mut last: Vec<int> = []
    for i in 0..(limit + 1) {
        comp.push(false)
        count.push(0)
        last.push(0)
    }
    let mut i: int = 2
    while i * i <= limit {
        if !comp[i as usize] {
            let mut j: int = i * i
            while j <= limit {
                comp[j as usize] = true
                j = j + i
            }
        }
        i += 1
    }
    let mut c: int = 0
    let mut l: int = 0
    for k in 0..(limit + 1) {
        if k >= 2 && !comp[k as usize] {
            c += 1
            l = k
        }
        count[k as usize] = c
        last[k as usize] = l
    }
    let mut first = true
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = s.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${count[n as usize]} ${last[n as usize]}")
        }
    }
}

